/** The guard predicates of the medication-administration machine, implemented once by the domain (MedicationAdministrationGuards). */
@Suppress("TooManyFunctions")
interface MedicationAdministrationPredicates {
    /**
     * the dose's order is a medication order for the dose's patient, its order.yaml state is active and its verification status is verified
     * (SI-02 clause a; CTRL-0002-3)
     */
    fun activeVerifiedOrder(facts: MedicationAdministrationFacts): Boolean

    /**
     * the dose's order is a medication order for the dose's patient, its order.yaml state is pending-verification and its verification
     * status is pending. A status of returned (returned to the prescriber for any reason: Verify with a control set A mismatch, or
     * ReturnToPrescriber) never satisfies it, so a returned order allows no override. Disjoint from activeVerifiedOrder (one state, one
     * status)
     */
    fun orderAwaitingVerification(facts: MedicationAdministrationFacts): Boolean

    /**
     * the order's orderable is on the governed emergency and first-dose override list (SAC-24, CTRL-0002-6; content [HUMAN], synthetic
     * samples NOT FOR CLINICAL USE); false when the orderable is unknown or the list is absent
     */
    fun emergencyOverrideListed(facts: MedicationAdministrationFacts): Boolean

    /**
     * no other dose of this order, or of any order in its replaces chain (R11 §7 replaces), is in-progress, completed or stopped, or is
     * entered-in-error after having been in-progress, completed or stopped; read under the order's schedule serialisation (DN-053 item 4);
     * false when that read cannot be made (an unknown fails)
     */
    fun firstDoseOfOrder(facts: MedicationAdministrationFacts): Boolean

    /** the dose's order is in order.yaml state pending-verification or active */
    fun orderAdministrable(facts: MedicationAdministrationFacts): Boolean

    /** the dose's order is in order.yaml state on-hold */
    fun orderOnHold(facts: MedicationAdministrationFacts): Boolean

    /**
     * the dose's order is in order.yaml state completed, revoked (discontinued or replaced) or entered-in-error: the orders module's answer
     */
    fun orderEnded(facts: MedicationAdministrationFacts): Boolean

    /**
     * the order is an infusion order (it carries a rate; MED-INF-01), so the dose starts as in-progress (§8.4 'in-progress (infusions) or
     * completed')
     */
    fun infusionOrder(facts: MedicationAdministrationFacts): Boolean

    /** the exact complement of infusionOrder */
    fun notInfusionOrder(facts: MedicationAdministrationFacts): Boolean

    /**
     * the order's dose is one value with a UCUM unit, not a range. A range dose (for example 2 to 4 mg) cannot be compared without a range
     * comparison that §2.1 allows only for titration rates (clause d), so it is refused with this predicate named until DN-053 item 6 is
     * decided
     */
    fun fixedDoseOrder(facts: MedicationAdministrationFacts): Boolean

    /**
     * the user issuing the command is an authenticated human user (never a system, interface, migration-loader, plugin or AI principal) who
     * holds the administration privilege for the order's route and drug class (§9.26; a Trust Plane answer; for an offline command, as
     * authenticated on the device). An unknown privilege requirement fails (DN-053 item 13)
     */
    fun administeringUserPrivileged(facts: MedicationAdministrationFacts): Boolean

    /**
     * the user issuing the command is an authenticated human user with any clinical role at the facility (a Trust Plane answer). It never
     * fails because a privilege configuration row is missing, so nothing configurable blocks completing or stopping an infusion
     */
    fun authenticatedClinicalUser(facts: MedicationAdministrationFacts): Boolean

    /**
     * the dose's clinical time is the command's issue time (the scan session's time on the issuing device, from the envelope; no
     * user-entered time), and that issue time is not later than the server's receipt time plus the governed clock-skew allowance (content
     * [HUMAN]; a missing allowance is zero). A dose given earlier and documented now is a back-entry (BackEnterAdministration, SI-10)
     */
    fun clinicalTimeContemporaneous(facts: MedicationAdministrationFacts): Boolean

    /**
     * the command's wristband scan was read from a patient wristband, never a bed, room, chart or other location label (SI-01 clause b;
     * CTRL-0001-4); its barcode decodes to an MRN (and the encounter); the identity service confirms the MRN's check digit and that the MRN
     * is the dose's patient's current MRN (CTRL-0001-7); and the patient's record holds at least one name form and a date of birth or the
     * approximate-DOB flag, which the channel shows for confirmation (SI-01 clauses a and d). A merged or retired MRN of the same patient
     * is refused (re-banding; see wristbandScanUnusable)
     */
    fun wristbandScanMatches(facts: MedicationAdministrationFacts): Boolean

    /**
     * the command carries no wristband scan that matches: none was read, the barcode was unreadable, or it decoded a merged or retired MRN
     * of this same patient (identity service). False when any wristband scan in the dose's scan log (this command's included) decoded an
     * MRN that the identity service does not confirm, with a valid check digit, as this patient's: another patient's MRN, or one it gives
     * no answer for (a wrong-patient scan is a hard stop no override passes); and false when the command's scan matches. Disjoint from
     * wristbandScanMatches
     */
    fun wristbandScanUnusable(facts: MedicationAdministrationFacts): Boolean

    /**
     * the user keyed the patient's MRN, whose check digit is valid and which the identity service confirms as the dose's patient's current
     * MRN, and keyed the date of birth, which equals the record's (or confirmed the approximate-DOB flag the record carries); the channel
     * showed the banner with the photo, every name form, the MRN and the date of birth at its recorded precision (SAC-01, SAC-02). B.3's
     * twoIdentifiersConfirmed, used only where the wristband scan cannot be (DN-053 item 5)
     */
    fun manualTwoIdentifiersConfirmed(facts: MedicationAdministrationFacts): Boolean

    /**
     * the command's product scan identified a product through the brand master (GTIN or in-house label) that is the order's product: for a
     * verified order, a product on its verified product line or on a dispense record for this patient and this order; for an order awaiting
     * verification, a product the governed brand-master mapping lists for the order's orderable (same drug, form and route). A different
     * drug, form, route or strength identity fails, and so does a lot whose expiry date is known and before the dose's clinical date. An
     * unknown expiry (a linear barcode without lot or expiry, and no stock record) does not fail: it is shown and recorded with the dose
     * (DN-053 item 2)
     */
    fun productIdentityMatches(facts: MedicationAdministrationFacts): Boolean

    /**
     * the command's product scan is absent or identified no product (no scan, unreadable, or not mapped in the brand master), and the
     * dose's scan log holds no scan that identified a product failing productIdentityMatches unless a pharmacist has since cleared it. So a
     * refused wrong-product, wrong-strength or expired-lot scan blocks the product-scan override for the dose (DN-053 item 3). Disjoint
     * from productIdentityMatches (the command's scan identified a product, or not)
     */
    fun productNotIdentified(facts: MedicationAdministrationFacts): Boolean

    /**
     * the user entered the amount given (an empty field, never prefilled with the ordered dose), and it equals the order's dose exactly in
     * the same UCUM unit (§2.1 clause b: two independently entered quantities). A unit mismatch is a mismatch (1000 mg against 1 g fails),
     * and the command handler then raises an order-review task (§2.1 clause b). No count, strength, volume or concentration is multiplied
     * (DN-053 item 6)
     */
    fun administeredAmountMatchesOrder(facts: MedicationAdministrationFacts): Boolean

    /**
     * the labelled content of the identified product, or of the supply the command names, equals exactly, in the same UCUM units, the
     * amount and volume (or concentration) of the order's verified product line, or for an order awaiting verification the order's own
     * ordered content (§2.1 clause b; MED-INF-01). The rate is not compared here: rate checks are titration (§2.1 clause d), outside this
     * machine
     */
    fun infusionContentMatchesOrder(facts: MedicationAdministrationFacts): Boolean

    /**
     * the supply being given is bound to this patient and order (SI-12 clauses d and e; CTRL-0012-7, CTRL-0012-8): (a) a dispense record
     * for this patient and this order that lists the scanned product and, when the scanned label is a pharmacy or in-house label, is the
     * record that label names; (b) ward stock of a product of the order's orderable that governed configuration lists as stocked on the
     * patient's unit (a bare GTIN of a product the unit does not stock is not cleared); or (c) a patient-supplied item only through its own
     * pharmacy relabel, scanned, naming this patient, with its lifecycle at administrable (received, identified, expiry-checked, relabelled
     * and flagged, §9.10). A patient-supplied item is never accepted without the scan of its relabel, so never on the product-scan override
     * (DN-053 item 11)
     */
    fun patientSuppliedCleared(facts: MedicationAdministrationFacts): Boolean

    /**
     * the dose is not high-alert, or an independent double check is recorded for it (SI-13; CTRL-0013-3, CTRL-0013-4). The dose is
     * high-alert when the formulary flag of the order's orderable or of the identified product is set, or the order's flag is unknown
     * (fails closed). The check names this dose and the product scanned in this command (product and lot), or on the product-scan override
     * the supply the command names; it was recorded after that scan and no longer before the command than the governed double-check window
     * (content [HUMAN], with a vendor default the CSO sets); and it was recorded by a second user who is not the administering user,
     * authenticated in their own right (badge and PIN) and privileged to double-check, who attested that patient, product and dose agree
     * with the order (DN-053 item 12)
     */
    fun highAlertCheckSatisfied(facts: MedicationAdministrationFacts): Boolean

    /**
     * the mode in which the command was issued (from its offline envelope; ADR-012, CTRL-0015-3) is online; or that mode is offline and the
     * order's pharmacist verification time is strictly before the start of that outage, as recorded by the device or edge agent (SI-15;
     * CTRL-0015-9). Losing the internet or the WAN alone leaves an on-site cell online (SI-15 last sentence); only a lost on-site cell,
     * edge-agent mode or mobile offline mode is offline. An unknown mode, verification time or outage start fails
     */
    fun offlineAllowed(facts: MedicationAdministrationFacts): Boolean

    /**
     * the command carries an override reason entered by the administering user and marked by the channel adapter as chosen by the user,
     * never prefilled, defaulted or carried over from another dose (SI-02 clause b; CTRL-0002-4). The channel adapter owns that mark; a
     * channel with no human chooser (API client, interface, migration loader, plugin, AI agent) supplies none, so the predicate fails
     */
    fun overrideReasonEntered(facts: MedicationAdministrationFacts): Boolean

    /** the override reason's code is on the governed product-scan override list (content [HUMAN]) */
    fun reasonOnScanOverrideList(facts: MedicationAdministrationFacts): Boolean

    /** the override reason's code is on the governed pre-verification (emergency and first-dose) override list (content [HUMAN]) */
    fun reasonOnVerificationOverrideList(facts: MedicationAdministrationFacts): Boolean

    /** the override reason's code is on the governed wristband-failure override list (content [HUMAN]) */
    fun reasonOnIdentityOverrideList(facts: MedicationAdministrationFacts): Boolean

    /**
     * the command carries a not-done reason that the user chose (the channel adapter's mark; never prefilled or defaulted), entered by the
     * acting user, whose code is one of held, refused, missed, npo or off-unit (§8.4 'Not done (held, refused, missed, NPO, off unit) |
     * Reason required'). 'missed' means not given; a dose the user reports as given is back-entered, never recorded as missed
     */
    fun notDoneReasonValid(facts: MedicationAdministrationFacts): Boolean

    /**
     * the clock reading in the facts is later than the dose's due time plus its late-dose window, and the dose has not been flagged late
     * yet. The window is fixed at creation from governed configuration (configurable, tighter for time-critical drugs; content [HUMAN]), or
     * the vendor default window the CSO sets where the tenant has none; it is never zero by omission (DN-053 item 14)
     */
    fun lateDoseWindowElapsed(facts: MedicationAdministrationFacts): Boolean

    /**
     * the command arrived through mobile or edge-agent sync with an authentic offline envelope (device-signed) whose mode at issue is
     * offline; a command issued online, or with a missing or unauthenticated envelope, fails
     */
    fun issuedOfflineAndSynced(facts: MedicationAdministrationFacts): Boolean

    /**
     * the command records a dose given off the system (paper during downtime or a cell loss, or in an emergency without scans): it
     * references the downtime or paper record, carries the paper's clinical time and the performer named on it, the clinical time is not
     * later than the server's receipt time, the user chose a back-entry reason (never defaulted), and the entry is labelled back-entry
     * (SI-10 clauses b and c; CTRL-0010-4, CTRL-0010-5)
     */
    fun backEntryDocumented(facts: MedicationAdministrationFacts): Boolean

    /**
     * the user holds the privilege that governed configuration requires for this command (marking an administration entered in error, or
     * back-entry), a Trust Plane answer (§9.26), and the audit record of the command can be written with it; an audit outage refuses the
     * command, it never runs unaudited. B.3's name, required on every exit from a terminal state (WP-0.5 spec §1.2); worded as in
     * order.yaml
     */
    fun privilegedAndAudited(facts: MedicationAdministrationFacts): Boolean

    /** the user chose an entered-in-error reason from the governed list (content [HUMAN]), never defaulted (§6.5) */
    fun errorReasonEntered(facts: MedicationAdministrationFacts): Boolean
}

