    /** Evaluates [predicate] with the domain's single implementation [predicates]. */
    @Suppress("CyclomaticComplexMethod")
    fun holds(
        predicate: MedicationAdministrationPredicate,
        predicates: MedicationAdministrationPredicates,
        facts: MedicationAdministrationFacts,
    ): Boolean =
        when (predicate) {
            MedicationAdministrationPredicate.ACTIVE_VERIFIED_ORDER -> predicates.activeVerifiedOrder(facts)
            MedicationAdministrationPredicate.ORDER_AWAITING_VERIFICATION -> predicates.orderAwaitingVerification(facts)
            MedicationAdministrationPredicate.EMERGENCY_OVERRIDE_LISTED -> predicates.emergencyOverrideListed(facts)
            MedicationAdministrationPredicate.FIRST_DOSE_OF_ORDER -> predicates.firstDoseOfOrder(facts)
            MedicationAdministrationPredicate.ORDER_ADMINISTRABLE -> predicates.orderAdministrable(facts)
            MedicationAdministrationPredicate.ORDER_ON_HOLD -> predicates.orderOnHold(facts)
            MedicationAdministrationPredicate.ORDER_ENDED -> predicates.orderEnded(facts)
            MedicationAdministrationPredicate.INFUSION_ORDER -> predicates.infusionOrder(facts)
            MedicationAdministrationPredicate.NOT_INFUSION_ORDER -> predicates.notInfusionOrder(facts)
            MedicationAdministrationPredicate.FIXED_DOSE_ORDER -> predicates.fixedDoseOrder(facts)
            MedicationAdministrationPredicate.ADMINISTERING_USER_PRIVILEGED -> predicates.administeringUserPrivileged(facts)
            MedicationAdministrationPredicate.AUTHENTICATED_CLINICAL_USER -> predicates.authenticatedClinicalUser(facts)
            MedicationAdministrationPredicate.CLINICAL_TIME_CONTEMPORANEOUS -> predicates.clinicalTimeContemporaneous(facts)
            MedicationAdministrationPredicate.WRISTBAND_SCAN_MATCHES -> predicates.wristbandScanMatches(facts)
            MedicationAdministrationPredicate.WRISTBAND_SCAN_UNUSABLE -> predicates.wristbandScanUnusable(facts)
            MedicationAdministrationPredicate.MANUAL_TWO_IDENTIFIERS_CONFIRMED -> predicates.manualTwoIdentifiersConfirmed(facts)
            MedicationAdministrationPredicate.PRODUCT_IDENTITY_MATCHES -> predicates.productIdentityMatches(facts)
            MedicationAdministrationPredicate.PRODUCT_NOT_IDENTIFIED -> predicates.productNotIdentified(facts)
            MedicationAdministrationPredicate.ADMINISTERED_AMOUNT_MATCHES_ORDER -> predicates.administeredAmountMatchesOrder(facts)
            MedicationAdministrationPredicate.INFUSION_CONTENT_MATCHES_ORDER -> predicates.infusionContentMatchesOrder(facts)
            MedicationAdministrationPredicate.PATIENT_SUPPLIED_CLEARED -> predicates.patientSuppliedCleared(facts)
            MedicationAdministrationPredicate.HIGH_ALERT_CHECK_SATISFIED -> predicates.highAlertCheckSatisfied(facts)
            MedicationAdministrationPredicate.OFFLINE_ALLOWED -> predicates.offlineAllowed(facts)
            MedicationAdministrationPredicate.OVERRIDE_REASON_ENTERED -> predicates.overrideReasonEntered(facts)
            MedicationAdministrationPredicate.REASON_ON_SCAN_OVERRIDE_LIST -> predicates.reasonOnScanOverrideList(facts)
            MedicationAdministrationPredicate.REASON_ON_VERIFICATION_OVERRIDE_LIST -> predicates.reasonOnVerificationOverrideList(facts)
            MedicationAdministrationPredicate.REASON_ON_IDENTITY_OVERRIDE_LIST -> predicates.reasonOnIdentityOverrideList(facts)
            MedicationAdministrationPredicate.NOT_DONE_REASON_VALID -> predicates.notDoneReasonValid(facts)
            MedicationAdministrationPredicate.LATE_DOSE_WINDOW_ELAPSED -> predicates.lateDoseWindowElapsed(facts)
            MedicationAdministrationPredicate.ISSUED_OFFLINE_AND_SYNCED -> predicates.issuedOfflineAndSynced(facts)
            MedicationAdministrationPredicate.BACK_ENTRY_DOCUMENTED -> predicates.backEntryDocumented(facts)
            MedicationAdministrationPredicate.PRIVILEGED_AND_AUDITED -> predicates.privilegedAndAudited(facts)
            MedicationAdministrationPredicate.ERROR_REASON_ENTERED -> predicates.errorReasonEntered(facts)
        }

    /** Applies [command] in [state] with [facts]; never changes state unless exactly one guard holds. */
    fun fire(
        state: MedicationAdministrationState,
        command: MedicationAdministrationCommand,
        predicates: MedicationAdministrationPredicates,
        facts: MedicationAdministrationFacts,
    ): Outcome<
        MedicationAdministrationState,
        MedicationAdministrationCommand,
        MedicationAdministrationPredicate,
        MedicationAdministrationEffect,
    > =
        spec.fire(state, command) { holds(it, predicates, facts) }
}
